// adj[u] holds (v, w) pairs. Return dist[1..n], using -1 for unreachable nodes.
vector<long long> dijkstra(int n, const vector<vector<pair<int, long long>>>& adj, int s) {
    // Write your solution here
    return vector<long long>(n + 1, -1);
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, long long>>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        long long w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
    }
    int s;
    cin >> s;
    vector<long long> dist = dijkstra(n, adj, s);
    for (int i = 1; i <= n; i++) cout << dist[i] << (i == n ? "\n" : " ");
    return 0;
}

